mapper.delete:
DELETE FROM sys99_print
 WHERE sys99_company_id      = #{companyId}
   AND sys99_person_id       = #{personId}
   AND sys99_window_class_nm LIKE #{windowClassName}

mapper.select:
SELECT icam10_rmk_cd AS rmk_code, icam10_rmk_nm AS rmk_name, icam10_cur_cd AS cur_code, f_calc_dual_fund_fee(icam10_company_id, icam10_icam_company_cd, icam10_fund_cd, icam10_std_date, icam10_fee) * CASE WHEN icam10_drcr_type = 'C' THEN 1 ELSE -1 END AS fee FROM icam10_fee LEFT OUTER JOIN sys15_corp ON (sys15_company_id = icam10_company_id AND sys15_corp_cd = icam10_icam_company_cd) WHERE icam10_company_id = #{p.companyId} AND icam10_std_date = #{p.stdDate} AND icam10_fund_cd = #{p.fundCode}
AND #{p.corpId} IN (sys15_corp_id, icam10_company_id)
AND upper(icam10_rmk_cd||icam10_rmk_nm) LIKE '%'||upper(#{p.searchText})||'%' ORDER BY icam10_rmk_cd

mapper.update:
UPDATE icam10_fee
   SET icam10_fee = #{fee}
 WHERE icam10_fee_id = #{feeId}
   AND icam10_company_id = #{companyId}

mapper.select:
SELECT sys12_day
  FROM sys12_calendar
 WHERE sys12_company_id = #{companyId}
   AND sys12_day BETWEEN #{startDate} AND #{closeDate}
 ORDER BY sys12_day
